"""Ledger entry model and the line parser."""

import datetime
import decimal
import re
from dataclasses import dataclass

__all__ = ["Entry", "ParseError", "parse", "parse_line", "split_lines", "parse_date"]

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_SEPARATOR_RE = re.compile(r"[ \t]+")
_LINE_END_RE = re.compile(r"\r\n|\n|\r")


class ParseError(ValueError):
    """A ledger line is wrong. ``.line`` is its 1-based number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))

    def __reduce__(self):
        return (ParseError, (self.line, self.reason))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: decimal.Decimal
    note: str = ""


def _show(text):
    text = repr(text)
    return text if len(text) <= 40 else text[:37] + "..."


def parse_date(text):
    """Parse ``YYYY-MM-DD`` into a date; ``ValueError`` when it is not a real date."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("not a YYYY-MM-DD date")
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("no such calendar date") from None


def split_lines(text):
    """Split on ``\\n``, ``\\r\\n`` or a lone ``\\r`` (nothing else), no empty tail."""
    if not text:
        return []
    lines = _LINE_END_RE.split(text)
    if lines[-1] == "":
        lines.pop()
    return lines


def parse_line(raw, number):
    """Parse one line; return an :class:`Entry`, or ``None`` for blank/comment lines."""
    line = raw.strip()
    if not line or line.startswith("#"):
        return None
    parts = _SEPARATOR_RE.split(line, 3)
    if len(parts) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE], got %s" % _show(line))
    date_text, category, amount_text = parts[0], parts[1], parts[2]
    note = parts[3].strip() if len(parts) == 4 else ""
    try:
        date = parse_date(date_text)
    except ValueError as exc:
        raise ParseError(number, "invalid date %s (%s)" % (_show(date_text), exc)) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(
            number, "invalid amount %s (use at most two decimals, e.g. -12.50)" % _show(amount_text)
        )
    return Entry(date, category.lower(), decimal.Decimal(amount_text), note)


def parse(text):
    """Turn ledger text into a list of :class:`Entry` in file order."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, raw in enumerate(split_lines(text), 1):
        entry = parse_line(raw, number)
        if entry is not None:
            entries.append(entry)
    return entries
"""Totals and filters over parsed entries."""

import datetime
import decimal

__all__ = ["balance", "by_category", "by_month", "filter_entries", "exact_sum"]


def exact_sum(amounts):
    """Sum Decimals without the default 28-digit context rounding."""
    amounts = list(amounts)
    digits = max((len(a.as_tuple().digits) for a in amounts), default=1)
    with decimal.localcontext() as ctx:
        ctx.prec = digits + len(str(len(amounts))) + 2
        total = decimal.Decimal(0)
        for amount in amounts:
            total += amount
    return total


def balance(entries):
    return exact_sum(e.amount for e in entries)


def _grouped(entries, key):
    groups = {}
    for entry in entries:
        groups.setdefault(key(entry), []).append(entry.amount)
    return {name: exact_sum(amounts) for name, amounts in groups.items()}


def by_category(entries):
    return _grouped(entries, lambda e: e.category)


def month_key(date):
    return "%04d-%02d" % (date.year, date.month)


def by_month(entries):
    return _grouped(entries, lambda e: month_key(e.date))


def _as_date(value):
    return value.date() if isinstance(value, datetime.datetime) else value


def filter_entries(entries, category=None, since=None, until=None):
    since, until = _as_date(since), _as_date(until)
    wanted = category.lower() if category is not None else None
    result = []
    for entry in entries:
        if wanted is not None and entry.category.lower() != wanted:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result
"""The ``pennywise`` command line."""

import csv
import decimal
import io
import json
import os
import re
import sys

from . import aggregate
from .model import ParseError, parse, parse_date, parse_line, split_lines

HELP = """\
usage: pennywise COMMAND ...

commands:
  balance FILE [--json]
  summary FILE [--by category|month] [--json]
  list FILE [--category C] [--since DATE] [--until DATE] [--json]
  add FILE DATE CATEGORY AMOUNT [NOTE]
  export FILE [--format csv]

FILE may be - to read the ledger from standard input (not for add).
exit status: 0 ok, 1 ledger/entry mistake, 2 unreadable file or bad command line
"""

USAGE = "usage: pennywise [-h] {balance,summary,list,add,export} ..."

# command -> (flag options, options taking a value)
_COMMANDS = {
    "balance": ({"--json"}, set()),
    "summary": ({"--json"}, {"--by"}),
    "list": ({"--json"}, {"--category", "--since", "--until"}),
    "export": (set(), {"--format"}),
    "add": (set(), set()),
}


class _Exit(Exception):
    """Stop with a status, an optional stderr message and optional stdout text."""

    def __init__(self, code, message=None, out=""):
        super().__init__(message)
        self.code = code
        self.message = message
        self.out = out


def _usage_error(message):
    return _Exit(2, "%s\npennywise: error: %s" % (USAGE, message))


def _parse_args(argv):
    """Return ``(command, positionals, options)``. A value is never mistaken for an option."""
    if not argv:
        raise _usage_error("a command is required")
    command, rest = argv[0], argv[1:]
    if command in ("-h", "--help"):
        raise _Exit(0, out=HELP)
    if command not in _COMMANDS:
        raise _usage_error("unknown command %r" % command)
    flags, valued = _COMMANDS[command]
    if rest and rest[0] in ("-h", "--help"):
        raise _Exit(0, out=HELP)
    options = {}
    if command == "add":
        # every argument is a value, however it starts
        positionals = rest[1:] if rest[:1] == ["--"] else rest
        if not 4 <= len(positionals) <= 5:
            raise _usage_error("add takes FILE DATE CATEGORY AMOUNT [NOTE]")
        return command, positionals, options
    positionals = []
    i = 0
    while i < len(rest):
        token = rest[i]
        i += 1
        if token == "--":
            positionals.extend(rest[i:])
            break
        if token in ("-h", "--help"):
            raise _Exit(0, out=HELP)
        if token.startswith("--"):
            name, eq, value = token.partition("=")
            if name in valued:
                if not eq:
                    if i >= len(rest):
                        raise _usage_error("option %s expects a value" % name)
                    value = rest[i]
                    i += 1
                options[name] = value
            elif name in flags and not eq:
                options[name] = True
            else:
                raise _usage_error("unrecognized option %r" % token)
        else:
            positionals.append(token)  # includes "-" and "-x"
    if len(positionals) != 1:
        raise _usage_error("%s takes exactly one FILE" % command)
    return command, positionals, options


def money(amount):
    """Format a Decimal with exactly two decimals; negative zero shows as 0.00."""
    with decimal.localcontext() as ctx:
        ctx.prec = len(amount.as_tuple().digits) + 4
        quantized = amount.quantize(decimal.Decimal("0.01"))
    if not quantized:
        quantized = abs(quantized)
    return format(quantized, "f")


def format_entry(entry):
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, money(entry.amount))
    return line + " " + entry.note if entry.note else line


def _read_ledger(path):
    try:
        if path == "-":
            stream = sys.stdin
            raw = getattr(stream, "buffer", stream).read()
        else:
            with open(path, "rb") as handle:
                raw = handle.read()
        return raw if isinstance(raw, str) else raw.decode("utf-8")
    except (OSError, ValueError) as exc:  # UnicodeDecodeError is a ValueError
        shown = "standard input" if path == "-" else path
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _Exit(2, "pennywise: cannot read %s: %s" % (shown, reason)) from None


def _load(path):
    text = _read_ledger(path)
    try:
        return parse(text)
    except ParseError as exc:
        raise _Exit(1, "pennywise: %s: %s" % ("standard input" if path == "-" else path, exc))


def _date_option(options, name):
    if name not in options:
        return None
    try:
        return parse_date(options[name])
    except ValueError as exc:
        raise _usage_error("option %s: invalid date %r (%s)" % (name, options[name], exc))


def _json(value):
    return json.dumps(value) + "\n"


def _cmd_balance(entries, options):
    total = money(aggregate.balance(entries))
    return _json({"balance": total}) if options.get("--json") else total + "\n"


def _cmd_summary(entries, options):
    by = options.get("--by", "category")
    if by not in ("category", "month"):
        raise _usage_error("option --by: invalid choice %r (choose category or month)" % by)
    totals = (aggregate.by_category if by == "category" else aggregate.by_month)(entries)
    names = sorted(totals)
    if options.get("--json"):
        return _json({name: money(totals[name]) for name in names})
    return "".join("%s  %s\n" % (name, money(totals[name])) for name in names)


def _listed(entries, options):
    category = options.get("--category")
    if category == "":
        raise _usage_error("option --category: empty value")
    since = _date_option(options, "--since")
    until = _date_option(options, "--until")
    chosen = aggregate.filter_entries(entries, category, since, until)
    return sorted(chosen, key=lambda e: e.date)  # stable: ties keep file order


def _cmd_list(entries, options):
    chosen = _listed(entries, options)
    if options.get("--json"):
        return _json(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": money(e.amount),
                    "note": e.note,
                }
                for e in chosen
            ]
        )
    return "".join(format_entry(e) + "\n" for e in chosen)


def _cmd_export(entries, options):
    fmt = options.get("--format", "csv")
    if fmt != "csv":
        raise _usage_error("option --format: invalid choice %r (choose csv)" % fmt)
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _listed(entries, {}):
        writer.writerow([e.date.isoformat(), e.category, money(e.amount), e.note])
    return buffer.getvalue()


def _cmd_add(positionals):
    path, date_text, category, amount_text = positionals[:4]
    note = positionals[4].strip() if len(positionals) == 5 else ""
    if path == "-":
        raise _Exit(2, "pennywise: add cannot write to standard input; give a file")
    existing = b""
    try:
        with open(path, "rb") as handle:
            existing = handle.read()
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise _Exit(2, "pennywise: cannot read %s: %s" % (path, exc.strerror or exc)) from None
    try:
        number = len(split_lines(existing.decode("utf-8"))) + 1
    except UnicodeDecodeError as exc:
        raise _Exit(2, "pennywise: cannot read %s: %s" % (path, exc)) from None

    def refuse(reason):
        return _Exit(1, "pennywise: %s: %s" % (path, ParseError(number, reason)))

    for label, value in (("date", date_text), ("category", category), ("amount", amount_text)):
        if not value or re.search(r"[ \t\r\n]", value):
            raise refuse("%s must be one word, got %r" % (label, value))
    if "\n" in note or "\r" in note:
        raise refuse("note must not contain a line break")
    line = " ".join([date_text, category, amount_text] + ([note] if note else []))
    try:
        entry = parse_line(line, number)
    except ParseError as exc:
        raise _Exit(1, "pennywise: %s: %s" % (path, exc)) from None
    if entry.date.isoformat() != date_text or entry.category != category.lower():
        raise refuse("date or category is malformed")
    shown = format_entry(entry)
    prefix = b"\n" if existing and not existing.endswith((b"\n", b"\r")) else b""
    try:
        payload = prefix + shown.encode("utf-8") + b"\n"
    except UnicodeEncodeError:
        raise refuse("entry is not valid text") from None
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise _Exit(2, "pennywise: cannot write %s: %s" % (path, exc.strerror or exc)) from None
    return shown + "\n"


_READERS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def _check_options(command, options):
    if command == "summary":
        _cmd_summary([], options)
    elif command == "list":
        _cmd_list([], options)
    elif command == "export":
        _cmd_export([], options)


def _run(argv):
    command, positionals, options = _parse_args(argv)
    if command == "add":
        return _cmd_add(positionals)
    # a bad command line is always 2, even when the ledger is bad too: check options first
    _check_options(command, options)
    entries = _load(positionals[0])
    return _READERS[command](entries, options)


def _silence_stdout():
    """Point fd 1 at /dev/null so the interpreter's exit flush stays quiet."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        os.dup2(fd, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        out = _run(args)
        code = 0
    except _Exit as stop:
        out, code = stop.out, stop.code
        if stop.message:
            sys.stderr.write(stop.message.rstrip("\n") + "\n")
    if out:
        try:
            sys.stdout.write(out)
            sys.stdout.flush()
        except BrokenPipeError:
            _silence_stdout()
        except (OSError, UnicodeError) as exc:
            _silence_stdout()
            sys.stderr.write("pennywise: cannot write output: %s\n" % exc)
            return 2
    return code
"""pennywise: read a plain-text household ledger and tell where the money went."""

from .aggregate import balance, by_category, by_month, filter_entries
from .model import Entry, ParseError, parse

__version__ = "0.1.0"

__all__ = [
    "Entry",
    "ParseError",
    "parse",
    "balance",
    "by_category",
    "by_month",
    "filter_entries",
]
import sys

from .cli import main

sys.exit(main())
