    positionals = []
    i = 0
    while i < len(rest):
        token = rest[i]
        i += 1
        if token == "--":
            positionals.extend(rest[i:])
            break
        if token in ("-h", "--help"):
            raise _Exit(0, out=HELP)
        if token.startswith("--"):
